export type ThresholdPosition = 'left' | 'right';
export interface StaticThreshold {
    value: number;
}
export interface StaticRangeThreshold {
    min: number;
    max: number;
}
export type DynamicThreshold = {
    value: number;
    date: Date;
}[];
export type DynamicRangeThreshold = {
    min: number;
    max: number;
    date: Date;
}[];
export type DynamicNumericThreshold = {
    value: number;
    point: number;
}[];
export type DynamicNumericRangeThreshold = {
    min: number;
    max: number;
    point: number;
}[];
export type ThresholdData = StaticThreshold | StaticRangeThreshold;
export type TimeseriesThresholdData = ThresholdData | DynamicThreshold | DynamicRangeThreshold;
export type TimeseriesThresholdPosition = ThresholdPosition;
export type HistogramThresholdData = ThresholdData | DynamicNumericThreshold | DynamicNumericRangeThreshold;
export type HistogramThresholdPosition = ThresholdPosition;
